 * @method
 * @name ipt_checkType_onclick
 * @description 「KRX」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_checkType_onclick = function(e){
    try {
        scwin.fnCheckList('type')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70301.ipt_checkType_onclick' }); }
