/**
 * @method
 * @name ipt_allClass_onclick
 * @description 「CLASS_ALL」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_allClass_onclick = function(e){
    try {
        scwin.fnCheckAll('class')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70301.ipt_allClass_onclick' }); }
};

/**
 * @method
 * @name ipt_checkClass_onclick
 * @description ipt_checkClass 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_checkClass_onclick = function(e){
    try {
        scwin.fnCheckList('class')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70301.ipt_checkClass_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex(); await scwin.goSearch();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70301.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_ReportDataList_oncellclick
 * @description grd_ReportDataList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ReportDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_ReportDataList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { /* TODO Stage2: 행 동작 미정의: scwin.previewPopOpen (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.previewPopOpen'); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_goSearch
 * @description go Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goSearch = async function () {
    const sbmOptions = {
        id: "tx_goSearch",
        method: "post",
        action: "/discls/form.do",
        ref: "dma_goSearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_88").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_ReportDataList_fillAct
 * @description grd Report Data List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ReportDataList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.fillAct' });
    }
};

/**
 * @method
 * @name enterSearchForm
 * @description enter Search Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.enterSearchForm = async function () {
    if (event.keyCode === 13) {
        await scwin.goSearch();
    }
};

/**
 * @method
 * @name goSearch
 * @description go Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch = async function () {
    if (!scwin.isCheckSelect('type')) {
        await alertE('담당기관을 선택하십시오.');
        return;
    }
    if (!scwin.isCheckSelect('class')) {
        await alertE('공시구분을 선택하십시오.');
        return;
    }
    blockLoading();
    const foldYn = $('#foldBt').hasClass('on') === true ? "Y" : "N";
    $c.util.getComponent('dma_goSearchReq').set('foldYn', foldYn);
    $c.util.getComponent('dma_goSearchReq').set('method', "formReport");
    (document.frmReportSearch || { elements: [] }).action = "/discls/form.do";
    await scwin.tx_goSearch();
};

/**
 * @method
 * @name isCheckSelect
 * @description is Check Select 처리
 * @param {*} checkType checkType
 * @returns {void}
 * @hidden N
 */
scwin.isCheckSelect = function (checkType) {
    if (checkType === "type") {
        if (($c.util.getComponent('ipt_allType').getValue() != null && String($c.util.getComponent('ipt_allType').getValue()) !== '') === true) {
            return true;
        }
        for (let i = 0; i < $c.util.getComponent('ipt_checkType').length; i++) {
            if ((String($c.util.getComponent(["ipt_checkType", "ipt_checkType_2", "ipt_checkType_3"][i]).getValue() || '') !== '') === true) {
                return true;
            }
        }
    } else {
        if (checkType === "class") {
            if (($c.util.getComponent('ipt_allClass').getValue() != null && String($c.util.getComponent('ipt_allClass').getValue()) !== '') === true) {
                return true;
            }
            for (let i = 0; i < $c.util.getComponent('dlt_ReportClass').getRowCount(); i++) {
                if ((['true', 'Y', '1'].indexOf(String($c.util.getComponent('dlt_ReportClass').getCellData(i, 'sprtBzDtlId'))) >= 0)=== true) {
                    return true;
                }
            }
        }
    }
    return false;
};

/**
 * @method
 * @name fnCheckAll
 * @description fn Check All 처리
 * @param {*} checkType checkType
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckAll = function (checkType) {
    if (checkType === "type") {
        for (let i = 0; i < $c.util.getComponent('ipt_checkType').length; i++) {
            $c.util.getComponent(["ipt_checkType", "ipt_checkType_2", "ipt_checkType_3"][i]).checked = (String($c.util.getComponent('ipt_allType').getValue() || "") !== "");
        }
    } else {
        if (checkType === "class") {
            for (let i = 0; i < $c.util.getComponent('dlt_ReportClass').getRowCount(); i++) {
                $c.util.getComponent('dlt_ReportClass').setCellData(i, 'sprtBzDtlId', (((String($c.util.getComponent('ipt_allClass').getValue() || "") !== "")) ? 'true' : 'false'));
            }
        }
    }
};

/**
 * @method
 * @name fnCheckList
 * @description fn Check List 처리
 * @param {*} checkType checkType
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckList = function (checkType) {
    let all_checked = true;
    if (checkType === "type") {
        for (let i = 0; i < $c.util.getComponent('ipt_checkType').length; i++) {
            let prefix = $c.util.getComponent(["ipt_checkType", "ipt_checkType_2", "ipt_checkType_3"][i]).getValue();
            if (!(String($c.util.getComponent(["ipt_checkType", "ipt_checkType_2", "ipt_checkType_3"][i]).getValue() || '') !== '')) {
                all_checked = false;
            }
        }
        $c.util.getComponent("ipt_allType").setValue(all_checked);
    } else {
        if (checkType === "class") {
            for (let i = 0; i < $c.util.getComponent('dlt_ReportClass').getRowCount(); i++) {
                prefix = $c.util.getComponent('dlt_ReportClass').getCellData(i, 'sprtBzDtlId');
                if (!(['true', 'Y', '1'].indexOf(String($c.util.getComponent('dlt_ReportClass').getCellData(i, 'sprtBzDtlId'))) >= 0)) {
                    all_checked = false;
                }
            }
            $c.util.getComponent("ipt_allClass").setValue(all_checked);
        }
    }
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

/**
 * @method
 * @name krxpage_pagenavigator_88_onclick
 * @description krxpage_pagenavigator_88 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_88_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_goSearchReq').set('pageIndex', pi);
        await scwin.tx_goSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldods70301.krxpage_pagenavigator_88_onclick" });
    }
};
